import {
  isPluginSample,
  PluginBase,
  PluginInitContext,
} from "@aloha-plugins/definitions/plugins-types";

export default class SampleServerPlugin implements PluginBase {
  type = "sample";
  version = "1.0.0";
  name = "fe-be-sample";
  async init(_context: PluginInitContext) {
    if (!isPluginSample(this)) {
      throw new Error("The plugin should have type === 'sample'");
    }
  }
}
